Same bug I believe... This is causing many of our builds to fail.  Here were my findings:

``` javascript
/* eslint indent: [2,2] */
function SillyFunction(arg, arg2) {
  return { irrelevant: true };
}

// validates fine in 2.0 and 2.1
SillyFunction(
  {
    value: true,
  },
  {
    _id: true,
  }
);

var haveFun = function () {

  // No longer validates here in 2.1.0
  SillyFunction(
    {
      value: true,
    },
    {
      _id: true,
    }
  );

  // I guess this is what it wants?  This validates in 2.1.0.
  SillyFunction(
  {
    value: true,
  },
  {
    _id: true,
  }
  );

  return "fun";
};

// Guess not! Same code doesn't validate here, outside of the block.
SillyFunction(
{
  value: true,
},
{
  _id: true,
}
);

haveFun();
```

